const services=[['site-vitrine','01','Sites vitrines','Un site clair qui présente vos services, rassure vos prospects et facilite les demandes de devis.'],['identite-visuelle','02','Identité visuelle','Un logo et des supports cohérents pour une entreprise reconnaissable, à l’écran comme sur papier.'],['seo-local','03','Référencement local','Des pages utiles et structurées pour développer votre présence sur les recherches de votre zone.'],['site-e-commerce','04','Boutiques & catalogues','Présentez vos produits et choisissez un parcours de commande adapté à votre activité.'],['refonte-site-web','05','Refonte de site','Modernisez un site peu lisible, réorganisez les contenus et simplifiez les prises de contact.'],['maintenance','06','Maintenance & suivi','Gardez vos informations à jour avec un accompagnement défini et un budget maîtrisé.']];
