add('/','Création site web Burkina Faso | WEB AFRICA','Création de sites web au Burkina Faso, identité visuelle et SEO local. Sites vitrines dès 119 000 FCFA. Découvrez les offres WEB AFRICA.',`<div class="wrap"><section class="hero"><div>${eyebrow('Communication visuelle & web · Burkina Faso')}<h1>Votre savoir-faire<br>mérite d’être<br><em>vu. Et choisi.</em></h1><p class="lead">Création de sites web au Burkina Faso et identité visuelle : nous aidons les PME à présenter une image sérieuse et à transformer l’intérêt en prise de contact.</p><div class="actions">${contact('Parlons de votre projet')}${link('realisations','Voir les concepts','btn outline')}</div><div class="checks"><span>Sites dès 119 000 FCFA</span><span>Devis gratuit</span><span>Adaptés au mobile</span></div></div><div class="stage"><span class="stage-label">VOTRE ENTREPRISE, SOUS SON MEILLEUR JOUR.</span>${mock()}<div class="seal"><span>Pensé pour<br><b>votre</b><br>activité</span></div><div class="float-card"><span class="float-icon">↗</span><span><b>Du premier regard au premier contact.</b>Un site qui rend votre offre plus claire.</span></div></div></section><div class="trust"><div><strong>Une image qui rassure</strong><span>Design soigné, informations utiles</span></div><div><strong>Un budget qui reste clair</strong><span>Périmètre et coûts détaillés au devis</span></div><div><strong>Un contact plus simple</strong><span>WhatsApp à portée de main</span></div></div></div>${section(`<div class="sectionhead"><div>${eyebrow('Ce que nous créons')}<h2>Une présence cohérente.<br>Du logo au site web.</h2></div><p>Le bon message, une identité reconnaissable et un site facile à utiliser : l’essentiel pour mieux présenter votre entreprise.</p></div>${servicesCards(3)}${link('services','Explorer tous les services','textlink')}`)}${section(`<div class="sectionhead"><div>${eyebrow('Votre métier au premier plan')}<h2>Des sites pensés pour<br>les entreprises d’ici.</h2></div><p>Chaque métier a ses preuves à montrer et ses questions à résoudre. Votre site doit les mettre en évidence.</p></div><div class="sector-grid">${sectors.map(([s,t,d])=>`<article class="sector"><h3>${t}</h3><p>${d}</p>${link('secteurs/'+s,'Voir les besoins de mon secteur ↗')}</article>`).join('')}</div>`,'dark')}${section(`<div class="sectionhead"><div>${eyebrow('Notre approche en images')}<h2>Projetez-vous dans<br>votre futur site.</h2></div><p>Trois concepts conçus pour illustrer notre approche. Des démonstrations, sans clients ni résultats commerciaux revendiqués.</p></div>${portfolio()}`)}${section(`<div class="sectionhead"><div>${eyebrow('Des offres lisibles')}<h2>Le bon site.<br>Au bon niveau de budget.</h2></div>${link('tarifs','Comparer les formules','textlink')}</div>${prices()}`)}${section(`${eyebrow('Simple, du début à la fin')}<h2>On avance ensemble,<br>étape par étape.</h2>${steps()}`)}${section(`<div class="sectionhead"><div>${eyebrow('Avant de vous lancer')}<h2>Vos questions,<br>nos réponses.</h2></div>${link('faq','Toutes les questions','textlink')}</div>${faq(4)}`)}${cta()}`);
