const serviceContent={
'site-vitrine':{title:'Création de site vitrine au Burkina Faso',intro:'Votre entreprise mérite une présentation aussi sérieuse que son travail. Un site vitrine rassemble votre offre, vos preuves et vos coordonnées dans un espace qui vous appartient.',price:'Dès 119 000 FCFA',blocks:[['Présentez clairement ce que vous faites','Une page d’accueil doit permettre de comprendre rapidement vos services, à qui ils s’adressent et comment vous joindre. Nous organisons vos textes autour des questions de vos futurs clients.'],['Faites une place aux preuves','Photos de chantiers, présentation des intervenants, références autorisées, programmes de formation : le contenu dépend de votre métier. Nous n’utilisons pas de faux avis ni de chiffres invérifiables.'],['Préparez la découverte sur Google','Chaque page reçoit un titre et une description propres. Les contenus sont structurés et reliés entre eux. Une base technique facilite l’exploration ; elle ne garantit pas une position.']],items:['3 à 10 pages selon la formule choisie','Design adapté aux mobiles et tablettes','Bouton WhatsApp et formulaire relié','Nom de domaine et hébergement 1 an offerts*']},
'identite-visuelle':{title:'Identité visuelle et communication au Burkina Faso',intro:'Des couleurs, une typographie et un logo qui racontent la même histoire, sur votre site, vos cartes et vos supports commerciaux.',price:'Logo dès 40 000 FCFA',blocks:[['Un logo utilisable au quotidien','L’offre de départ comprend deux pistes graphiques, la finalisation d’une piste et deux séries de corrections. Livraison en SVG, PNG transparent et PDF pour les usages convenus.'],['Une identité qui tient ensemble','Le kit identité, à partir de 75 000 FCFA, ajoute une palette, des typographies recommandées et une mini-charte. Les licences de polices ou visuels payants restent séparées.'],['Des supports adaptés à votre communication','Carte de visite, affiche, présentation commerciale ou visuels pour Facebook : nous définissons les formats et volumes au devis. Impression, photo et production vidéo sont chiffrées séparément.']],items:['Logo et déclinaisons','Mini-charte graphique en option','Supports digitaux et imprimés sur devis','Fichiers prêts pour les usages définis']},
'seo-local':{title:'Référencement local à Ouagadougou et au Burkina Faso',intro:'Aidez les prospects qui cherchent vos services dans votre zone à comprendre votre offre et à prendre contact.',price:'Audit initial dès 50 000 FCFA',blocks:[['Commencer par les bonnes recherches','Nous identifions les services recherchés et les questions auxquelles votre site doit répondre. Une page utile sur votre activité vaut mieux qu’une série de pages presque identiques où seul le nom de ville change.'],['Améliorer les pages existantes','L’audit initial couvre jusqu’à dix pages et fournit une liste d’actions priorisées. L’implémentation des corrections, la rédaction et le suivi mensuel sont chiffrés à part. Les sites que nous créons incluent déjà une base SEO.'],['Relier le site à votre présence locale','Si votre activité est éligible, nous pouvons accompagner la préparation d’une fiche Google Business Profile. Les coordonnées doivent être exactes ; la validation dépend de Google. Aucun faux avis ni adresse inventée.'],['Mesurer dans la durée','Après mise en ligne publique, Search Console peut aider à suivre les recherches et l’indexation. Le suivi sert à améliorer les pages, sans promettre un nombre de clients ou une première place.']],items:['Audit des contenus et de la structure','Mots-clés liés à vos activités réelles','Conseils de présence locale','Plan d’actions priorisé']},
'site-e-commerce':{title:'Création de boutique en ligne au Burkina Faso',intro:'Du catalogue avec demande sur WhatsApp à une boutique avec panier, choisissons un parcours que vous pouvez réellement gérer.',price:'Boutique sur commande — sur devis',blocks:[['Catalogue ou paiement en ligne ?','Pour tester une offre, un catalogue simple et une demande WhatsApp peuvent suffire. Une boutique avec panier convient lorsque vous avez déjà défini vos produits, vos stocks, vos livraisons et votre service client.'],['Un périmètre de départ raisonnable','La base e-commerce comprend jusqu’à vingt produits simples, un panier, des frais de livraison fixes et une prise en main. Variantes complexes, marketplace, abonnement ou connexion au stock sont hors périmètre.'],['Des paiements à valider avant le devis','Un paiement Mobile Money ou par carte nécessite un prestataire compatible et un compte marchand accepté. Les frais de transaction et d’abonnement du prestataire sont séparés. Aucune intégration n’est promise avant vérification.']],items:['Jusqu’à 20 produits simples','Design mobile et fiches produits','Panier et commande selon périmètre','Formation à la gestion du catalogue']},
'refonte-site-web':{title:'Refonte de site web à Ouagadougou',intro:'Votre site existe mais ne présente plus correctement votre entreprise ? Repartons de ce qui fonctionne pour améliorer le reste.',price:'Refonte dès 150 000 FCFA',blocks:[['Identifier ce qui bloque','Navigation confuse, anciennes informations, contact difficile à trouver : un diagnostic aide à distinguer les corrections urgentes d’une refonte plus profonde.'],['Conserver les contenus utiles','Nous recensons les pages existantes et les liens à préserver. Si une adresse change, un plan de redirection est préparé selon les possibilités de l’hébergement.'],['Définir un périmètre avant de commencer','Le tarif de départ concerne un site simple de trois pages avec contenus récupérables. Migration complexe, refonte de boutique et nettoyage après piratage demandent un diagnostic et un devis distincts.']],items:['Diagnostic du site existant','Nouvelle structure et design mobile','Vérification des liens et contacts','Plan de migration selon le projet']},
'maintenance':{title:'Maintenance et suivi de site web au Burkina Faso',intro:'Un service ou un numéro change ? Votre site doit rester une source d’information fiable pour vos clients.',price:'Dès 10 000 FCFA / mois',blocks:[['Un entretien défini, sans formule illimitée','L’offre de base inclut un contrôle mensuel de disponibilité, une sauvegarde mensuelle, la vérification des liens et trente minutes de petites modifications. Le temps non utilisé n’est pas reporté.'],['Adapter le suivi au type de site','Un site statique et une boutique WordPress n’ont pas les mêmes besoins. Pour un CMS, les mises à jour, licences, sauvegardes et procédures de restauration sont précisées au contrat.'],['Séparer entretien et évolution','Une nouvelle page, une nouvelle fonctionnalité ou une intervention urgente sort du suivi de base. Domaine et hébergement sont renouvelés séparément ; les coûts sont annoncés avant commande.']],items:['Contrôle mensuel','Sauvegarde mensuelle','30 minutes de modifications','Évolutions sur devis']}}
for(const [s,v] of Object.entries(serviceContent)){add('services/'+s,v.title+' | WEB AFRICA',v.intro,head(v.title,v.intro,'Service')+section(`<div class="split"><div class="prose">${v.blocks.map(([t,d])=>`<h2>${t}</h2><p>${d}</p>`).join('')}<h2>Comment se déroule votre projet ?</h2><p>Nous cadrons vos besoins, validons le périmètre et le calendrier, puis préparons une première version. Les retours sont regroupés avant livraison. Votre devis détaille les options et les coûts récurrents.</p>${link('tarifs','Consulter les tarifs et les conditions','textlink')}</div><aside class="aside"><span class="eyebrow">Budget de départ</span><h3>${v.price}</h3><ul>${v.items.map(x=>`<li>${x}</li>`).join('')}</ul>${contact('Demander un devis')}<p class="note">Montant final confirmé selon votre besoin.</p></aside></div>`)+cta(),{service:v.title,price:v.price});}
const tarifsPricing=()=>`<div class="pricing">${plans.map((p,i)=>`<article class="pricecard ${p.featured?'featured':''}">${p.badge?`<span class="ribbon">${p.badge}</span>`:''}<h3>${p.name}</h3><p>${p.for}</p><div class="price">${p.priceDisplay || (typeof p.price === 'number' ? p.price.toLocaleString('fr-FR')+' <small>FCFA</small>' : p.price)}</div><p class="price-sub">${p.sub || 'Création, paiement unique'}</p><ul>${p.items.map(x=>`<li>${x}</li>`).join('')}</ul><div class="pricecard-actions"><a class="${p.featured?'btn-popy-primary':'btn-popy-glass'}" href="#estimateur"><span>Choisir cette formule</span> <span class="arrow">↓</span></a></div><p class="note"><strong>Délai :</strong> ${p.delay}</p></article>`).join('')}</div>`;

add('tarifs','Tarifs création site web Burkina Faso | WEB AFRICA','Pack Vitrine Essentiel dès 119 000 FCFA, Pack Vitrine Pro + Admin de 250 000 à 450 000 FCFA, Option Espace Membre dès +200 000 FCFA. Comparez les formules et estimez en direct.',head('Des tarifs clairs &amp; transparents.<br><span class="gradient-cyan">Estimez votre devis en direct.</span>','Pack Vitrine Essentiel à 119 000 FCFA, Vitrine Pro + Admin de 250 000 à 450 000 FCFA, Option Espace Membre dès +200 000 FCFA. Consultez les formules ci-dessous et utilisez le simulateur interactif pour obtenir votre chiffrage proforma.','Tarifs & Estimateur')+section(`<div class="sectionhead"><div><span class="eyebrow-cyan">— NOS 3 FORMULES CLÉ EN MAIN</span><h2>Le bon niveau d'investissement pour votre entreprise.</h2></div><p>Des tarifs transparents en FCFA, paiement 50% commande / 50% livraison, nom de domaine .com standard et hébergement 1 an offerts*.</p></div>${tarifsPricing()}`)+`<div id="estimateur" class="tarifs-estimator-container"><div class="sectionhead wrap"><div><span class="eyebrow-cyan">— ESTIMATEUR &amp; SIMULATEUR EN DIRECT</span><h2>Composez votre projet et obtenez votre devis en 30 secondes.</h2></div><p>Sélectionnez votre formule, ajustez le volume de pages et ajoutez l'Espace Membre selon vos besoins. Votre somme totale en FCFA se calcule en temps réel avec récapitulatif proforma prêt pour WhatsApp.</p></div>${getConfigurateurHtml(true)}</div>`+section(sub100kBanner)+section(siteTypesGuide())+section(`<div class="sectionhead"><div><span class="eyebrow-cyan">— TRANSPARENCE TOTALE</span><h2>Les coûts à prévoir après la création &amp; options.</h2></div><p>Tout ce qui concerne l'hébergement futur, la maintenance et les extensions.</p></div><div class="tablewrap"><table><thead><tr><th>Poste</th><th>Budget indicatif</th><th>À savoir</th></tr></thead><tbody><tr><td>Domaine standard + hébergement simple</td><td>30 000–50 000 FCFA/an</td><td>Selon fournisseur. Domaine .bf, e-mails et licences sur devis.</td></tr><tr><td>Maintenance facultative</td><td>Dès 10 000 FCFA/mois</td><td>Contrôle et sauvegarde mensuels, 30 minutes de modifications.</td></tr><tr><td>Page supplémentaire (Pack Essentiel)</td><td>20 000 FCFA</td><td>Sur la structure existante, contenus fournis.</td></tr><tr><td>Page supplémentaire (Pack Pro + Admin)</td><td>40 000 FCFA</td><td>Architecture administrable complète, jusqu'à 10 pages.</td></tr><tr><td>Option Espace Membre & Authentification</td><td>+200 000 à +550 000 FCFA</td><td>Base de données cloud sécurisée, rôles, dépôt de dossiers.</td></tr><tr><td>Logo & identité visuelle</td><td>Dès 40 000 FCFA</td><td>2 pistes, finalisation de 1 piste, 2 séries de corrections.</td></tr><tr><td>Audit SEO local initial</td><td>Dès 50 000 FCFA</td><td>Jusqu’à 10 pages ; mise en œuvre des recommandations séparée.</td></tr></tbody></table></div><div class="prose"><h2>Ce qui est inclus, ce qui reste à définir.</h2><p>Les formules comprennent l’adaptation mobile, l’intégration de vos contenus, les métadonnées, les liens de contact et une prise en main. Les textes et images doivent vous appartenir ou être autorisés. La rédaction complète, les traductions, les photos, les licences payantes, un CMS et les fonctions spécifiques sont chiffrés si nécessaires.</p><h2>Un paiement en deux étapes.</h2><p>50 % à la commande, puis 50 % après validation, avant mise en ligne définitive. Les délais commencent lorsque tous les contenus et l’acompte sont reçus. Le devis confirme le montant total payable, les éventuelles taxes applicables, le calendrier et les modalités de livraison.</p></div>`)+cta());
add('demonstrations','Nos démonstrations — Savoir-faire web | WEB AFRICA','Explorez trois concepts de sites BTP, cabinet et restaurant. Démonstrations de l’approche graphique et des parcours de contact WEB AFRICA.',head('Des idées concrètes<br>pour votre futur site.','Ces concepts illustrent une direction visuelle et un parcours utilisateur. Ce ne sont pas des références clients, et aucun résultat commercial ne leur est attribué.','Nos démonstrations')+section(`<div class="filters" aria-label="Filtrer les concepts"><button aria-pressed="true" data-filter="all">Tous les concepts</button><button aria-pressed="false" data-filter="btp">BTP</button><button aria-pressed="false" data-filter="cabinet">Cabinet</button><button aria-pressed="false" data-filter="restaurant">Restaurant</button></div>${portfolio()}`)+cta());
for(const [s,t,d] of projects){add('demonstrations/'+s,t+' — Démonstration créative | WEB AFRICA',d,head(t,d,'Démonstration WEB AFRICA')+section(`<div class="split"><div><div class="project-thumb">${mock(s)}</div><p class="note">Modèle de démonstration conçu pour WEB AFRICA. Prêt à être adapté à votre secteur.</p><div class="prose"><h2>Le besoin illustré</h2><p>${s==='btp'?'Une entreprise de BTP et génie civil doit démontrer son assise technique et sa capacité d’exécution. Ce concept valorise les chantiers livrés, le parc d’engins lourds et la demande de cotation directe.':s==='cabinet'?'Un cabinet doit rendre ses missions compréhensibles tout en inspirant confiance. Ce concept donne la priorité aux expertises, à la méthode et à la présentation de l’intervenant.':'Un restaurant gastronomique et grillades doit susciter l’envie immédiatement. Ce concept met en valeur les spécialités locales, la carte interactive avec prix en FCFA et les commandes ou réservations directes sur WhatsApp.'}</p><h2>Le parcours proposé</h2><p>Comprendre l’envergure depuis l’accueil, consulter les réalisations et parcs d’engins, puis solliciter un devis ou appel d’offres en quelques clics via WhatsApp.</p><h2>Ce qui serait personnalisé</h2><p>Vos photos réelles de chantiers, vos engins, vos agréments techniques, votre logo et vos coordonnées remplaceront les éléments illustratifs pour refléter votre entreprise.</p></div></div><aside class="aside"><h3>Un site dans cet esprit ?</h3><p>La formule Vitrine PME constitue une base idéale à adapter à vos contenus.</p>${contact('Parler de mon projet','btn','?offre=Vitrine%20PME')}${link('demonstrations','Retour aux démonstrations','textlink')}</aside></div>`)+cta());}
const sectorDetails={btp:['Des chantiers qui parlent pour vous','Pour un maître d’ouvrage ou un partenaire, vos réalisations sont souvent plus convaincantes qu’un long discours. Préparez des photos autorisées, le type de travaux, votre rôle et la période de chaque projet.','Services par type de travaux, galerie de chantiers, moyens disponibles, zone d’intervention et formulaire de devis.','Localisation du chantier, type de bâtiment, état d’avancement et délai envisagé.'],cabinets:['Rendre votre expertise compréhensible','Un dirigeant qui cherche du conseil veut savoir si vous comprenez son problème. Présentez vos missions avec des situations concrètes et les livrables attendus. N’utilisez des titres ou qualifications que s’ils sont exacts.','Expertises, méthode, présentation des intervenants, ressources et demande de rendez-vous.','Domaine du besoin, taille de la structure et objectif de l’accompagnement.'],restaurant:['Donner faim et faciliter la réservation','Pour un restaurant ou un maquis haut de gamme, les clients veulent voir les plats, les prix en FCFA et réserver en un clin d’œil sur WhatsApp. Présentez vos spécialités avec des photos alléchantes.','Carte interactive des plats et boissons, formules midi et soir, espace lounge/terrasse et réservation WhatsApp 1-clic.','Nombre de convives, choix du créneau (midi ou soir), terrasse ou salle climatisée et commande anticipée de plats braisés.'],immobilier:['Des biens faciles à consulter','Une annonce doit permettre de comprendre l’emplacement, le type de bien et les conditions sans multiplier les messages. Ne publiez que des annonces à jour et des photos autorisées.','Fiches de biens, caractéristiques, secteur, disponibilité et demande de visite.','Référence du bien, projet de location ou d’achat et disponibilités pour une visite.'], 'import-export':['Rassurer vos partenaires à distance','Un prospect professionnel cherche une offre précise et un interlocuteur identifiable. Présentez vos catégories de produits, votre rôle dans la chaîne logistique et vos zones réellement desservies.','Catalogue, prestations logistiques, zones d’intervention, documents commerciaux autorisés et demande de cotation.','Produit ou marchandise, quantité, départ, destination et échéance.'],services:['Une offre claire pour gagner du temps','Quand vos services sont bien expliqués, les premiers échanges peuvent porter directement sur le besoin. Regroupez votre offre en catégories compréhensibles et indiquez votre zone d’intervention réelle.','Présentation, services, exemples autorisés, questions fréquentes et demande de devis.','Service souhaité, zone d’intervention, contexte et calendrier.']};
for(const [s,t,d] of sectors){const [heading,why,include,brief]=sectorDetails[s];add('secteurs/'+s,'Site web '+t+' au Burkina Faso | WEB AFRICA',d,head('Un site web pour '+t.toLowerCase()+'.',d,'Votre secteur')+section(`<div class="split"><div class="prose"><h2>${heading}</h2><p>${why}</p><h2>Les pages à privilégier</h2><p>${include}</p><h2>Une demande de contact mieux préparée</h2><p>${brief}</p><h2>Une présence adaptée au Burkina Faso</h2><p>Nous privilégions des informations lisibles sur téléphone, des pages légères et un lien WhatsApp pour poursuivre la discussion. Votre zone de service est précisée dans les contenus sans inventer d’adresse ou d’implantation.</p>${link('creation-site-web-ouagadougou','Découvrir notre approche à Ouagadougou','textlink')}</div><aside class="aside"><h3>Base conseillée : Vitrine PME</h3><p>Jusqu’à 5 pages, dès 119 000 FCFA. Les catalogues étendus et fonctions métier sont chiffrés à part.</p>${contact('Décrire mon besoin','btn','?secteur='+encodeURIComponent(t))}</aside></div>`)+cta());}
add('creation-site-web-ouagadougou','Création site web Ouagadougou | Agence web WEB AFRICA','Création de sites web à Ouagadougou pour PME, BTP, cabinets et restaurants. Design mobile, contact WhatsApp et offres dès 119 000 FCFA.',head('Création de site web<br>à Ouagadougou.','Une présence web claire pour présenter votre entreprise et faciliter les demandes de vos prospects à Ouagadougou.','Agence web · Ouagadougou')+section(`<div class="split"><div class="prose"><h2>Le site qui complète votre présence sur le terrain.</h2><p>Une recommandation, une carte de visite ou une publication Facebook peut amener un prospect à chercher votre nom. Votre site rassemble ce qu’il doit connaître : vos prestations, vos preuves, votre zone d’intervention et un moyen simple de vous joindre.</p><h2>Un parcours adapté aux échanges locaux</h2><p>Pour les PME, les cabinets et les entreprises du BTP à Ouagadougou, une discussion directe reste souvent nécessaire avant un devis. Le site aide à préparer cet échange. Le visiteur peut préciser son besoin puis poursuivre sur WhatsApp ou par e-mail.</p><h2>Des contenus propres à votre entreprise</h2><p>Vos services et réalisations doivent être décrits avec précision. Si vous intervenez dans plusieurs secteurs de Ouagadougou, nous mentionnons les zones que vous confirmez, sans créer de faux bureaux. Une adresse ne sera publiée qu’après votre validation.</p><h2>Les éléments à préparer</h2><ul><li>Votre nom commercial, logo et coordonnées à jour.</li><li>Une liste claire des prestations et des zones desservies.</li><li>Des photos réelles dont vous détenez les droits.</li><li>Les questions habituelles de vos prospects.</li></ul><h2>Quel budget prévoir ?</h2><p>Le Pack Vitrine Essentiel démarre à 119 000 FCFA pour 3 à 5 pages tout inclus (domaine .com et hébergement 1 an offerts). Pour un besoin spécifique ou un site One Page avec budget inférieur à 100 000 FCFA, une étude personnalisée sur mesure est possible sur simple demande. La formule Vitrine Pro + Admin, de 250 000 à 450 000 FCFA, inclut un espace d'administration autonome pour modifier textes et photos jusqu'à 10 pages.</p>${link('tarifs','Comparer les formules','textlink')}<h2>Et en dehors de Ouagadougou ?</h2><p>Le cadrage et les validations peuvent se faire à distance pour un projet au Burkina Faso. Les besoins de déplacement ou de production de photos sont étudiés séparément.</p></div><aside class="aside"><h3>Vous cherchez une agence web à Ouagadougou ?</h3><p>Présentez votre activité et votre besoin. Nous vous orienterons vers une formule proportionnée.</p>${contact('Préparer ma demande')}<p class="note">Aucun déplacement ou rendez-vous physique n’est inclus sans accord préalable.</p></aside></div>`)+cta());
add('a-propos','À propos de WEB AFRICA | Communication visuelle & web','Découvrez l’approche WEB AFRICA : communication visuelle, sites web accessibles et accompagnement clair pour les entreprises du Burkina Faso.',head('Une présence web sérieuse.<br>À taille humaine.','WEB AFRICA associe création de sites web modernes et identité visuelle pour aider les entreprises et indépendants du Burkina Faso à valoriser leur activité.','L’agence')+section(`<div class="split"><div class="prose"><h2>Le sérieux se voit dans les détails.</h2><p>Une offre compréhensible, des coordonnées faciles à trouver, un site rapide sur téléphone : la crédibilité se construit avec des choix concrets. Fondé par Abdoul Salam Koanda à Ouagadougou, WEB AFRICA privilégie la proximité, l’efficacité et les résultats concrets sur le terrain.</p><h2>Une offre accessible et cadrée</h2><p>Nous concevons des sites vitrines modernes pour les artisans, PME, cabinets et commerçants. Le budget reste clair et proportionné à un périmètre précis. Les projets complexes sont étudiés avant tout engagement.</p><h2>Des échanges simples & directs</h2><p>Vous avez un interlocuteur direct et réactif sur WhatsApp. Vous participez aux décisions clés : objectifs, contenus, design puis validation. Le devis fixe les livrables, les corrections incluses et les frais récurrents.</p><h2>Des modèles prêts à être adaptés</h2><p>Les démonstrations présentées sur ce site illustrent nos standards graphiques et de navigation. Elles sont conçues pour être personnalisées rapidement avec vos couleurs, vos textes et vos photos réelles.</p></div><aside class="aside"><h3>Nos engagements</h3><ul><li>Interlocuteur direct à Ouagadougou</li><li>Prix clairs et devis respecté</li><li>Validation étape par étape</li><li>Sites 100% adaptés aux mobiles</li></ul>${link('demonstrations','Voir les démonstrations','textlink')}</aside></div>`)+section(steps())+cta());
const articles=[['prix-site-web-burkina-faso','Quel budget prévoir pour un site web au Burkina Faso ?','Création, hébergement, maintenance : séparez les dépenses pour comparer les devis.',[['Comparer le périmètre avant le prix','Deux devis peuvent porter sur des prestations très différentes. Vérifiez le nombre de pages, la rédaction, les corrections, la gestion des contenus et les fonctions. Un prix bas n’est intéressant que si le site répond réellement au besoin.'],['Distinguer création et dépenses annuelles','La création est généralement une dépense initiale. Le domaine et l’hébergement se renouvellent ; la maintenance peut être facultative. Chez WEB AFRICA, notre Pack Vitrine Essentiel tout compris (3 à 5 pages, nom de domaine .com standard et hébergement 1 an offerts) est à 119 000 FCFA, et les formules avec espace d’administration autonome (Vitrine Pro + Admin) s’échelonnent de 250 000 à 450 000 FCFA selon le nombre de pages. Pour les besoins plus légers avec un budget inférieur à 100 000 FCFA, un devis personnalisé est réalisé sur mesure.'],['Préparer les contenus pour mieux maîtriser le budget','Une liste de services, des photos autorisées et des coordonnées complètes évitent une production improvisée. Prévoyez une enveloppe supplémentaire pour la rédaction complète, les traductions ou les prises de vue si nécessaire.'],['Demander un total clair','Avant de signer, demandez le montant total payable, les coûts annuels, le calendrier, les accès remis et ce qui déclenche un devis complémentaire. Consultez nos tarifs pour voir un exemple de périmètre détaillé.']]],['site-web-ou-facebook','Un site web est-il utile si vous avez déjà Facebook ?','Comprendre le rôle de chaque canal pour mieux organiser votre communication.',[['Facebook pour faire découvrir votre activité','Vos publications et vos campagnes peuvent susciter l’intérêt. Mais un prospect doit parfois parcourir beaucoup de publications pour retrouver vos services, vos horaires ou une réalisation précise.'],['Un site pour organiser les informations','Une page dédiée à chaque service rend l’offre plus facile à consulter et à partager. Votre domaine peut figurer sur vos cartes de visite, vos devis et vos supports imprimés. Il devient un point de référence.'],['WhatsApp pour poursuivre la discussion','Le site peut préparer un message avec le service recherché, le contexte et le budget indicatif. Le prospect reste libre de l’envoyer. Cette continuité évite de lui faire répéter toutes les informations.'],['Commencer à la bonne échelle','Si votre offre est simple, une page bien construite peut suffire. Des services variés, des réalisations et des programmes de formation justifient plusieurs pages. Le nombre de pages doit servir la compréhension.']]],['preparer-projet-site-web','Les éléments à préparer avant de créer votre site','Une liste pratique pour les entreprises et indépendants du Burkina Faso.',[['Définissez une action prioritaire','Voulez-vous des demandes de devis, des visites, des demandes d’inscription ou des appels ? Choisissez une action principale pour guider les textes et les boutons.'],['Rassemblez les informations utiles','Préparez vos coordonnées, vos zones de service, une description de chaque prestation et les questions habituelles. Vérifiez les dates, horaires et prix avant publication.'],['Sélectionnez vos preuves','Choisissez des photos autorisées et des références que vous avez le droit de publier. Si vous débutez, décrivez votre méthode et présentez des concepts clairement signalés. Ne remplacez pas l’absence de références par de faux témoignages.'],['Organisez la validation','Désignez une personne qui regroupe les retours. Validez d’abord la structure, puis le design et les contenus. Conservez une liste des accès à remettre et fixez les modalités de maintenance.']]]];
add('conseils','Conseils pour votre site web au Burkina Faso | WEB AFRICA','Guides pratiques pour choisir votre site, comprendre les tarifs et préparer votre projet web au Burkina Faso.',head('Les bonnes questions.<br>Avant le premier clic.','Des conseils simples pour préparer votre projet et choisir une présence web adaptée à votre entreprise.','Conseils')+section(`<div class="cards">${articles.map(([s,t,d],i)=>`<article class="card"><span class="number">GUIDE 0${i+1}</span><h3>${t}</h3><p>${d}</p>${link('conseils/'+s,'Lire le guide','textlink')}</article>`).join('')}</div>`)+cta());
for(const [s,t,d,blocks]of articles)add('conseils/'+s,t+' | WEB AFRICA',d,head(t,d,'Guide pratique')+section(`<article class="prose"><p class="note">WEB AFRICA · Mis à jour le 11 octobre 2026</p>${blocks.map(([h,p])=>`<h2>${h}</h2><p>${p}</p>`).join('')}<p>${link('tarifs','Voir les tarifs','textlink')} &nbsp; ${link('services/site-vitrine','Découvrir les sites vitrines','textlink')}</p></article>`)+cta(),{article:true});
add('faq','FAQ création site web & tarifs | WEB AFRICA','Les réponses sur les prix, délais, maintenance, domaine, Google et paiement pour votre projet de site web au Burkina Faso.',head('Tout ce que vous<br>voulez savoir.','Prix, délais, propriété du site et suivi : les réponses pour préparer votre projet sereinement.','Questions fréquentes')+section(faq())+cta(),{faq:true});
add('contact','Contact & devis site web Burkina Faso | WEB AFRICA','Demandez votre devis WEB AFRICA. WhatsApp +226 69 29 13 37 / +226 65 41 48 99 ou e-mail : présentez votre projet de site web ou de communication visuelle.',head('Parlons de votre<br>prochain chapitre.','Décrivez votre activité et ce dont vous avez besoin. Préparez votre demande puis envoyez-la sur WhatsApp ou par e-mail.','Contact & devis')+section(`<div class="split"><div><form id="brief"><div class="formgrid"><div class="field"><label for="name">Votre nom *</label><input id="name" name="name" autocomplete="name" required maxlength="100"></div><div class="field"><label for="company">Votre entreprise ou projet</label><input id="company" name="company" autocomplete="organization" maxlength="150"></div><div class="field"><label for="sector">Votre secteur</label><select id="sector" name="sector"><option>PME & services</option>${sectors.slice(0,5).map(([,t])=>`<option>${t}</option>`).join('')}<option>Autre</option></select></div><div class="field"><label for="offer">Votre besoin</label><select id="offer" name="offer"><option>À définir ensemble</option>${plans.map(p=>`<option>${p.name}</option>`).join('')}<option>Identité visuelle</option><option>Boutique en ligne</option><option>Refonte</option><option>SEO local</option><option>Maintenance</option></select></div><div class="field"><label for="budget">Budget indicatif</label><select id="budget" name="budget"><option>À discuter</option>Moins de 150 000 FCFA</option><option>150 000 à 250 000 FCFA</option><option>250 000 à 400 000 FCFA</option><option>Plus de 400 000 FCFA</option></select></div><div class="field"><label for="deadline">Délai souhaité</label><input id="deadline" name="deadline" placeholder="Ex. : dans un mois" maxlength="100"></div><div class="field full"><label for="message">Votre projet en quelques mots *</label><textarea id="message" name="message" required minlength="10" maxlength="3000" placeholder="Votre activité, vos services, ce que vous attendez du site…"></textarea></div></div><p class="note">Ce formulaire prépare un message dans votre navigateur. Rien n’est envoyé avant votre action dans WhatsApp ou votre messagerie. Évitez les données sensibles. ${link('confidentialite','Confidentialité')}.</p><div class="actions"><button class="btn orange" type="submit">Préparer ma demande ↗</button></div></form><div id="result" hidden><h2>Votre demande est prête.</h2><pre class="brief-result" id="brief-text"></pre><div class="actions"><a id="send-wa" class="btn orange" target="_blank" rel="noopener">Envoyer sur WhatsApp ↗</a><a id="send-mail" class="btn outline">Envoyer par e-mail</a><button id="copy-brief" class="btn outline">Copier</button></div><p id="copy-status" role="status"></p><p class="note">Votre demande n’a pas encore été envoyée. Validez l’envoi dans l’application choisie.</p></div></div><aside class="aside"><h3>Un échange direct.</h3><p>Vous préférez nous écrire ou nous appeler directement ?</p><p><strong>WhatsApp & appel</strong><br><a href="https://wa.me/${config.whatsapp}" target="_blank" rel="noopener">+226 69 29 13 37 ↗</a><br><a href="tel:+22665414899">+226 65 41 48 99</a></p><p><strong>E-mail</strong><br><a href="mailto:${config.email}" style="overflow-wrap:anywhere">${config.email}</a></p><p><strong>Zone de service</strong><br>Burkina Faso · projets à Ouagadougou et accompagnement à distance.</p><p class="note">Un premier échange permet de confirmer le périmètre, le budget et la disponibilité.</p></aside></div>`));
add('confidentialite','Confidentialité | WEB AFRICA','Fonctionnement du formulaire de contact, liens WhatsApp et traitement des informations transmises à WEB AFRICA.',head('Vos informations,<br>en toute clarté.','Cette notice décrit la gestion de vos données et le respect de votre vie privée.','Confidentialité')+section(`<div class="prose"><h2>Le formulaire de contact</h2><p>Les champs servent à préparer un message dans votre navigateur. Ce site ne stocke pas le formulaire dans une base de données. Les informations sont transmises uniquement lorsque vous confirmez l’envoi dans WhatsApp ou votre messagerie.</p><h2>Les échanges reçus</h2><p>Les informations que vous envoyez à WEB AFRICA servent à comprendre votre demande et à échanger sur votre projet. Pour toute question ou demande de suppression, écrivez à <a href="mailto:${config.email}">${config.email}</a> ou contactez-nous au +226 69 29 13 37 / +226 65 41 48 99.</p><h2>Hébergement & services externes</h2><p>Le site est hébergé par Hostinger International Ltd. (61 Lordou Vironos Street, 6023 Larnaca, Chypre - www.hostinger.com). WhatsApp et votre fournisseur de messagerie appliquent leurs propres conditions d'utilisation.</p><h2>Mesure d’audience</h2><p>Cette version n’intègre aucun traceur publicitaire ni outil d’analyse d’audience intrusif.</p><p class="note">Notice mise à jour en octobre 2026. WEB AFRICA est un service freelance indépendant dirigé par Abdoul Salam Koanda à Ouagadougou.</p></div>`),{noindex:true});
add('mentions-legales','Mentions légales | WEB AFRICA','Informations légales, statut freelance et hébergeur du site WEB AFRICA.',head('Informations<br>sur le site.','Statut freelance, coordonnées directes et hébergement du site WEB AFRICA.','Mentions légales')+section(`<div class="prose"><h2>Éditeur du site</h2><p>Le site <strong>WEB AFRICA</strong> est édité par <strong>KOANDA ABDOUL SALAM</strong>, exerçant en tant que <strong>freelance / travailleur indépendant</strong> sous le nom commercial <strong>WEB AFRICA</strong> pour ses prestations de création de sites web et communication visuelle.<br>Statut juridique : Prestataire indépendant / freelance (en nom propre, sans constitution en société).<br>Responsable de la publication : KOANDA ABDOUL SALAM.<br>Adresse : quartier Garghin, Ouagadougou, Burkina Faso.<br>WhatsApp &amp; Téléphone : <a href="https://wa.me/22669291337">+226 69 29 13 37 ↗</a><br>Téléphone direct : <a href="tel:+22665414899">+226 65 41 48 99</a><br>E-mail : <a href="mailto:${config.email}">${config.email}</a>.</p><h2>Statut professionnel</h2><p>Activité exercée en freelance (nom propre). Aucun statut sociétaire ni forme d'entreprise collective n'est revendiqué. Les interventions s’effectuent sur devis convenu avant exécution.</p><h2>Hébergement</h2><p>Le site est hébergé par :<br><strong>Hostinger International Ltd.</strong><br>Adresse : 61 Lordou Vironos Street, 6023 Larnaca, Chypre.<br>Site officiel : <a href="https://www.hostinger.com" target="_blank" rel="noopener noreferrer">www.hostinger.com</a>.</p><h2>Contenus et démonstrations</h2><p>Les concepts Bâtir, Cap Conseil et Horizon sont des réalisations de démonstration originales conçues par WEB AFRICA pour illustrer nos savoir-faire. Les tarifs mentionnés sont des bases indicatives adaptées au périmètre convenu.</p></div>`),{noindex:true});

add('demarrer','Brief projet : site, affiche, vidéo IA, logo | WEB AFRICA','Préparez votre projet avec les formulaires WEB AFRICA : site web, affiche, vidéo publicitaire IA et logo. Envoyez un brief complet sur WhatsApp.',head('Votre projet commence ici.','Choisissez votre prestation. Quelques minutes pour réunir les informations utiles et recevoir une proposition adaptée.','Préparer mon projet')+section('<div class="brief-choices">'+Object.entries(briefs).map(([key,v],i)=>'<a class="brief-choice" href="/brief/'+key+'/"><small>0'+(i+1)+' / BRIEF PROJET</small><strong>'+v.name+' ↗</strong><p>'+v.short+'</p><small>'+v.time+'</small></a>').join('')+'</div><p class="note">Vous avez besoin de plusieurs prestations ? Remplissez un brief par prestation et précisez qu’elles appartiennent au même projet. Si votre besoin est encore flou, '+link('contact','contactez-nous directement')+'.</p>')+section('<div class="steps"><article><strong>01</strong><h3>Votre activité</h3><p>Qui vous êtes, ce que vous proposez et votre public.</p></article><article><strong>02</strong><h3>Votre besoin</h3><p>Les contenus, les formats et les préférences propres au projet.</p></article><article><strong>03</strong><h3>Votre organisation</h3><p>Budget, délais, fichiers et personne qui valide.</p></article><article><strong>04</strong><h3>Votre brief</h3><p>Relisez, téléchargez et envoyez dans votre messagerie.</p></article></div>'));
for(const [key,v] of Object.entries(briefs))add('brief/'+key,'Brief '+v.name+' — Préparer votre projet | WEB AFRICA',v.intro,head('Préparons votre '+v.name.toLowerCase()+'.',v.intro,'Questionnaire de projet')+section('<div class="brief-shell" id="project-brief" data-type="'+key+'"><noscript><p>Activez JavaScript pour utiliser le questionnaire guidé. Vous pouvez aussi '+link('contact','nous contacter directement')+'.</p></noscript></div>')+'<script type="module" src="/brief.js"></script>',{noindex:true});
add('services/affiche','Création d’affiches et flyers au Burkina Faso | WEB AFRICA','Affiches, flyers et visuels publicitaires adaptés à l’impression et aux réseaux sociaux. Remplissez le brief pour un devis précis.',head('Votre message.<br>Au premier regard.','Une affiche doit faire comprendre l’essentiel rapidement : l’offre, son intérêt et la prochaine action à réaliser.','Affiches & flyers')+section('<div class="split"><div class="prose"><h2>Du message au format de diffusion</h2><p>Nous hiérarchisons votre titre, vos informations et vos coordonnées. Le support est adapté à son usage : publication Facebook, statut WhatsApp, flyer ou affiche imprimée.</p><h2>Les bonnes informations dès le départ</h2><p>Le brief recueille le texte exact, les dates, les prix, les dimensions, les coordonnées et les références visuelles. Vous pouvez fournir des liens vers vos photos et logos ou les joindre ensuite au message.</p><h2>Un devis selon les déclinaisons</h2><p>Le prix dépend du nombre de concepts, des formats, de la création de visuels et des corrections. Les frais d’impression et l’achat éventuel de visuels sont séparés.</p></div><aside class="aside"><h3>Préparons votre affiche</h3><p>5 à 8 minutes pour décrire votre besoin.</p>'+link('brief/affiche','Remplir le brief affiche ↗','btn orange')+'</aside></div>'));
add('services/video-publicitaire-ia','Vidéo publicitaire IA au Burkina Faso | WEB AFRICA','Préparez votre vidéo publicitaire IA : scénario, voix, format, offre et diffusion. Un brief complet pour cadrer votre projet WEB AFRICA.',head('Une vidéo qui met<br>votre offre en scène.','Une publicité pensée autour d’un message clair, d’un format adapté et d’un appel à l’action.','Vidéo publicitaire IA')+section('<div class="split"><div class="prose"><h2>Une idée avant les images</h2><p>Nous cadrons le message, le public et l’action recherchée avant la production. Le scénario sert à organiser les scènes et à valider les informations commerciales.</p><h2>IA et éléments de marque</h2><p>Les images générées peuvent varier d’une scène à l’autre. Les photos produit, logos et emballages exacts sont donc à fournir lorsqu’ils doivent rester fidèles. La voix, la langue et les effets demandés sont soumis à vérification de faisabilité.</p><h2>Un budget lié au travail demandé</h2><p>Durée, nombre de scènes, voix, retouches et formats influencent le devis. Les licences payantes, la diffusion publicitaire et les déclinaisons supplémentaires sont précisées séparément. Les droits sur les éléments fournis doivent être disponibles.</p></div><aside class="aside"><h3>Préparons votre vidéo</h3><p>Le brief détaille l’offre, le scénario, la voix, les formats et les contraintes.</p>'+link('brief/video','Remplir le brief vidéo ↗','btn orange')+'</aside></div>'));
add('configurateur','Configurateur de devis site web en direct | WEB AFRICA','Calculez votre Pack Vitrine Essentiel (119 000 FCFA), Pack Vitrine Pro + Admin (250 000 à 450 000 FCFA) et option Espace Membre (+200 000 à +550 000 FCFA) en direct avec total calculé.',getConfigurateurHtml());
add('estimateur','Estimateur de devis site web en direct | WEB AFRICA','Estimez votre Pack Vitrine Essentiel (119 000 FCFA), Pack Vitrine Pro + Admin (250 000 à 450 000 FCFA) et option Espace Membre (+200 000 à +550 000 FCFA) en direct avec total calculé.',getConfigurateurHtml());
for(const p of pages){
 if(p.slug==='services')p.body=p.body.replace('</div></section>', '<div class="actions">'+link('services/affiche','Affiches & flyers','btn outline')+link('services/video-publicitaire-ia','Vidéo publicitaire IA','btn outline')+'</div></div></section>');
 if(p.slug==='services/identite-visuelle')p.body=p.body.replace('/demarrer/', '/brief/logo/');
 if(p.slug==='services/site-vitrine')p.body=p.body.replace('</aside>', '<div class="space-top">'+link('configurateur','Estimer mon devis en direct ↗','btn orange')+'</div></aside>');
}

const assetVer = Date.now().toString(36);
upgrade(pages,{add,head,section,cta,prices,faq,steps,link,contact,eyebrow,assetVer,siteTypesGuide,sub100kBanner});
// Assemblage du bundle CSS haute performance (1 seule requête réseau)
const cssBundle = [
  fs.existsSync('fonts.css') ? fs.readFileSync('fonts.css', 'utf8') : (fs.existsSync('dist/fonts.css') ? fs.readFileSync('dist/fonts.css', 'utf8') : ''),
  fs.existsSync('style.css') ? fs.readFileSync('style.css', 'utf8') : (fs.existsSync('dist/style.css') ? fs.readFileSync('dist/style.css', 'utf8') : ''),
  fs.existsSync('brand.css') ? fs.readFileSync('brand.css', 'utf8') : (fs.existsSync('dist/brand.css') ? fs.readFileSync('dist/brand.css', 'utf8') : ''),
  fs.existsSync('brief.css') ? fs.readFileSync('brief.css', 'utf8') : (fs.existsSync('dist/brief.css') ? fs.readFileSync('dist/brief.css', 'utf8') : ''),
  fs.existsSync('upgrade.css') ? fs.readFileSync('upgrade.css', 'utf8') : (fs.existsSync('dist/upgrade.css') ? fs.readFileSync('dist/upgrade.css', 'utf8') : ''),
  fs.existsSync('configurateur.css') ? fs.readFileSync('configurateur.css', 'utf8') : (fs.existsSync('dist/configurateur.css') ? fs.readFileSync('dist/configurateur.css', 'utf8') : '')
].join('\n');
fs.mkdirSync('dist', { recursive: true });
fs.writeFileSync('dist/bundle.css', cssBundle);

// Assemblage du bundle JS (1 seule requête réseau en différé)
const jsBundle = [
  fs.existsSync('app.js') ? fs.readFileSync('app.js', 'utf8') : '',
  fs.existsSync('experience.js') ? fs.readFileSync('experience.js', 'utf8') : '',
  fs.existsSync('configurateur.js') ? fs.readFileSync('configurateur.js', 'utf8') : ''
].join('\n;\n');
fs.writeFileSync('dist/bundle.js', jsBundle);

const footer=()=>`<footer><div class="wrap"><div class="footgrid"><div>${link('/','<span class="brand-logo"><img src="/logo-web-africa.webp?v='+assetVer+'" alt="WEB AFRICA" width="540" height="266"></span>','brand')}<p>Votre savoir-faire mérite d’être vu.<br>Communication visuelle et création de sites web au Burkina Faso.</p></div><div><h3>Nos expertises</h3>${services.map(([s,,t])=>link('services/'+s,t)).join('')}</div><div><h3>Explorer</h3>${nav.slice(1).map(([s,t])=>link(s,t)).join('')}${link('faq','Questions fréquentes')}${link('creation-site-web-ouagadougou','Agence web Ouagadougou')}</div><div><h3>Parlons de votre projet</h3><a href="https://wa.me/${config.whatsapp}" target="_blank" rel="noopener noreferrer">+226 69 29 13 37 (WhatsApp) ↗</a><a href="tel:+22665414899">+226 65 41 48 99 (Appel direct)</a><a href="mailto:${config.email}" style="overflow-wrap:anywhere">${config.email}</a>${link('demarrer','Préparer mon projet')}${link('contact','Contact direct')}<p>Burkina Faso<br>Ouagadougou & à distance</p></div></div><div class="footbottom"><span>© 2026 WEB AFRICA. Freelance création web & communication au Burkina Faso.</span><span>${link('mentions-legales','Mentions légales')} &nbsp; · &nbsp; ${link('confidentialite','Confidentialité')} &nbsp; · &nbsp; ${link('credits','Crédits photos')} &nbsp; · &nbsp; <button type="button" data-open-preferences>Cookies & préférences</button></span></div></div></footer>`;
for(const p of pages){let schema=[{'@context':'https://schema.org','@type':'Organization','@id':origin+'/#organization',name:'WEB AFRICA',url:origin,telephone:['+22669291337','+22665414899'],email:config.email,areaServed:[{'@type':'Country',name:'Burkina Faso'},{'@type':'City',name:'Ouagadougou'}]}];if(p.slug!=='/')schema.push({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Accueil',item:url('/')},{'@type':'ListItem',position:2,name:p.title.split('|')[0].trim(),item:url(p.slug)}]});if(p.service)schema.push({'@context':'https://schema.org','@type':'Service',name:p.service,provider:{'@id':origin+'/#organization'},areaServed:'Burkina Faso',url:url(p.slug)});if(p.faq)schema.push({'@context':'https://schema.org','@type':'FAQPage',mainEntity:faqs.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))});if(p.article)schema.push({'@context':'https://schema.org','@type':'Article',headline:p.title.split('|')[0].trim(),author:{'@type':'Organization',name:'WEB AFRICA'},datePublished:'2026-10-11',dateModified:'2026-10-11',mainEntityOfPage:url(p.slug)});const html=`<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.title)}</title><meta name="description" content="${esc(p.description)}"><meta name="robots" content="${!config.publicIndexing||p.noindex?'noindex,nofollow':'index,follow'}"><link rel="canonical" href="${url(p.slug)}"><meta name="theme-color" content="#164bd6"><meta property="og:type" content="${p.article?'article':'website'}"><meta property="og:title" content="${esc(p.title)}"><meta property="og:description" content="${esc(p.description)}"><meta property="og:url" content="${url(p.slug)}"><meta property="og:locale" content="fr_FR"><meta property="og:site_name" content="WEB AFRICA"><meta property="og:image" content="${origin}/social.svg"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/png" sizes="32x32" href="/favicon-32x32.png?v=${assetVer}"><link rel="icon" type="image/png" sizes="16x16" href="/favicon-16x16.png?v=${assetVer}"><link rel="icon" type="image/svg+xml" href="/favicon.svg?v=${assetVer}"><link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png?v=${assetVer}"><link rel="stylesheet" href="/bundle.css?v=${assetVer}"><script type="application/ld+json">${JSON.stringify(schema).replaceAll('<','\\u003c')}</script><script src="/bundle.js?v=${assetVer}" defer></script></head><body><a class="skip" href="#main">Aller au contenu</a><header><div class="wrap nav">${link('/','<span class="brand-logo"><img src="/logo-web-africa.webp?v='+assetVer+'" alt="WEB AFRICA" width="540" height="266"></span>','brand')}<button class="menu" aria-controls="navigation" aria-expanded="false">Menu ☰</button><nav class="navlinks" id="navigation" aria-label="Navigation principale">${nav.map(([s,t])=>{const href=s===''?'/':`/${s}/`;const isCurrent=s===''?(p.slug==='/'):(p.slug===s||p.slug.startsWith(s+'/'));return `<a href="${href}" ${isCurrent?'aria-current="page"':''}>${t}</a>`;}).join('')}${contact('Demander un devis','btn-popy-primary nav-cta-btn')}</nav></div></header><main id="main">${p.body}</main>${footer()}<dialog id="preferences" class="preferences-panel" aria-labelledby="preferences-title"><h2 id="preferences-title">Une navigation à votre rythme.</h2><p>Aucun traceur publicitaire ni outil d’audience dans cette version. Réglez les effets visuels selon votre confort.</p><label class="pref-check"><input type="checkbox" id="pref-motion" checked><span>Activer les effets de relief au survol.<br>La réduction des animations de votre appareil reste prioritaire.</span></label><label class="pref-check"><input type="checkbox" id="pref-remember"><span>Mémoriser mon choix pendant six mois avec un cookie de préférences.</span></label><p><a href="/cookies/">Détails sur les cookies</a> · <a href="/confidentialite/">Confidentialité</a></p><div class="actions"><button class="btn orange" id="preferences-save">Appliquer mes choix</button><button class="btn outline" id="preferences-close">Fermer</button><button class="btn outline" id="preferences-delete">Supprimer le choix mémorisé</button></div><p id="pref-status" role="status"></p></dialog><a class="wa" href="https://wa.me/${config.whatsapp}?text=${encodeURIComponent('Bonjour WEB AFRICA, je souhaite échanger sur mon projet.')}" target="_blank" rel="noopener" aria-label="Contacter WEB AFRICA sur WhatsApp"><svg class="wa-svg" viewBox="0 0 24 24" width="20" height="20" fill="currentColor" aria-hidden="true"><path d="M12.031 6.172c-3.181 0-5.767 2.586-5.768 5.766-.001 1.298.38 2.27 1.019 3.287l-.582 2.128 2.182-.573c.978.58 1.911.928 3.145.929 3.178 0 5.767-2.587 5.768-5.766 0-3.18-2.587-5.771-5.764-5.771zm3.392 8.244c-.144.405-.837.774-1.17.824-.312.045-.698.074-2.123-.518-1.554-.645-2.548-2.224-2.625-2.327-.077-.103-.625-.833-.625-1.587 0-.754.394-1.125.534-1.28.14-.155.308-.195.411-.195.103 0 .205.001.296.006.096.004.224-.037.351.267.13.31.442 1.079.481 1.157.039.078.065.17.013.273-.051.103-.077.167-.154.257-.077.09-.162.201-.231.27-.078.077-.159.16-.068.315.091.156.403.665.865 1.077.595.53 1.096.694 1.252.772.156.077.247.069.338-.037.091-.106.39-.454.494-.61.103-.156.207-.13.348-.078.141.052.894.421 1.048.498.154.077.257.115.295.18.038.065.038.375-.106.78zM12 2C6.477 2 2 6.477 2 12c0 1.891.524 3.661 1.434 5.176L2 22l4.956-1.399C8.406 21.493 10.15 22 12 22c5.523 0 10-4.477 10-10S17.523 2 12 2z"/></svg><span>Discuter sur WhatsApp</span><span class="wa-arrow">↗</span></a></body></html>`;const dest=p.slug==='/'?'dist/index.html':path.join('dist',p.slug,'index.html');fs.mkdirSync(path.dirname(dest),{recursive:true});fs.writeFileSync(dest,html.replaceAll('style="overflow-wrap:anywhere"','class="safe-wrap"').replaceAll('style="margin-top:24px"','class="space-top"'));}
